"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type PeerCanvasPanel = {
  id: string;
  title: string;
  eyebrow?: string;
  body: string;
  tone?: string;
};

export type PeerCanvasProps = {
  panels: PeerCanvasPanel[];
  className?: string;
  activeId?: string | null;
  defaultActiveId?: string | null;
  onActiveIdChange?: (id: string | null) => void;
};

/**
 * Split canvas: focusing one peer panel dims the rest and drives the shared
 * story column — classic linked choreography for dashboards.
 */
function PeerCanvas({
  panels,
  className,
  activeId,
  defaultActiveId = null,
  onActiveIdChange,
}: PeerCanvasProps) {
  const [internal, setInternal] = React.useState<string | null>(
    defaultActiveId ?? panels[0]?.id ?? null,
  );
  const focusedId = activeId !== undefined ? activeId : internal;
  const focused =
    panels.find((p) => p.id === focusedId) ?? panels[0] ?? null;

  const setFocused = (id: string | null) => {
    if (activeId === undefined) setInternal(id);
    onActiveIdChange?.(id);
  };

  return (
    <div
      className={cn(
        "grid gap-3 overflow-hidden rounded-2xl border border-border bg-card p-3 shadow-[var(--shadow-soft)] sm:grid-cols-[1.1fr_0.9fr] sm:p-4",
        className,
      )}
    >
      <div
        key={focused?.id ?? "empty"}
        className="relative min-h-[9.5rem] overflow-hidden rounded-xl border border-border/70 bg-muted/40 p-4"
        style={{
          backgroundImage: focused?.tone
            ? `linear-gradient(145deg, color-mix(in oklch, ${focused.tone} 22%, transparent), transparent 60%)`
            : undefined,
        }}
      >
        <div className="text-[11px] font-medium uppercase tracking-[0.14em] text-muted-foreground">
          {focused?.eyebrow ?? "Focus"}
        </div>
        <div className="mt-2 text-2xl font-semibold tracking-tight">
          {focused?.title ?? "—"}
        </div>
        <p className="mt-2 max-w-sm text-sm leading-relaxed text-muted-foreground">
          {focused?.body}
        </p>
      </div>

      <div className="grid gap-2">
        {panels.map((panel) => {
          const active = panel.id === focusedId;
          return (
            <button
              key={panel.id}
              type="button"
              onMouseEnter={() => setFocused(panel.id)}
              onFocus={() => setFocused(panel.id)}
              className={cn(
                "rounded-xl border px-3 py-2.5 text-left transition-[opacity,background-color,transform] duration-200",
                active
                  ? "border-primary/40 bg-primary/5 opacity-100"
                  : "border-border/70 bg-background/60 opacity-50 hover:opacity-85",
              )}
            >
              <div className="text-sm font-medium">{panel.title}</div>
              <div className="mt-0.5 line-clamp-1 text-xs text-muted-foreground">
                {panel.body}
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}

export { PeerCanvas };
